import base64


def base64ify(bytes_or_str):
    """
    Encode a string into Base64 using UTF-8.

    :param str bytes_or_str: input string to be encoded.
                             It will be encoded to bytes using UTF-8 before Base64 encoding.

    :returns: Base64-encoded ASCII string.
    :rtype: str
    """
    input_bytes = bytes_or_str.encode('utf8')
    output_bytes = base64.standard_b64encode(input_bytes)

    return output_bytes.decode('ascii')


def decode_base64_encoded_file(file_path):
    """
    Decode a Base64-encoded file in place.

    This function reads the contents of a file that is assumed to be
    Base64-encoded text, decodes it, overwrites the file with the decoded
    plain text, and returns the decoded content.

    :param str file_path: path to the file containing Base64-encoded content.

    :returns: decoded file content as a string.
    :rtype: str
    """
    with open(file_path) as fh:
        content = fh.read()
    content = base64.b64decode(content).decode()

    with open(file_path, 'w') as fh:
        fh.write(content)

    return content
